    Err(PromptError::Provider(error)) => {
        eprintln!("the model call failed ({:?}): {error}", error.kind());
    }
    Err(PromptError::MaxTurns { max_turns, .. }) => {
        eprintln!("used all {max_turns} model calls without a final answer");
    }
