    Err(error) => eprintln!("run failed: {error}"),
}

use rig::ProviderError;


fn log_failure(error: &ProviderError) {
    eprintln!("{:?} (retryable: {}): {error}", error.kind(), error.is_retryable());
    if let Some(status) = error.provider_response_status() {
        eprintln!("provider returned HTTP {status}");
    }
    if let Some(request_id) = error.provider_request_id() {
        eprintln!("quote this request id to the provider: {request_id}");
    }
    match error.provider_response_json() {
        Ok(Some(body)) => eprintln!("error payload: {body}"),
        Ok(None) => {}
        Err(_) => eprintln!("non-JSON body: {:?}", error.provider_response_body()),
    }
}

use rig::completion::PromptError;


fn is_retryable(error: &PromptError) -> bool {
    match error {
        PromptError::Provider(error) => error.is_retryable(),
        PromptError::Report(report) => report.is_retryable(),
        _ => false,
    }
}

